import string
import random

def task_func(length, random_seed=None):
    BRACKETS = "(){}[]"
    if length < 0:
        raise ValueError("length must be non-negative")

    rng = random.Random(random_seed)
    pool = string.ascii_lowercase + BRACKETS
    return "".join(rng.choice(pool) for _ in range(length))
